package levels_test

import (
	"context"
	"encoding/json"
	"os"
	"path/filepath"
	"slices"
	"testing"

	"qinqin/internal/dict"
	"qinqin/internal/levels"
)

// bundledPacks is the committed default seed root (HSK 3.0 is deliberately
// not in it: it is an optional local pack, see plugins/data/README.md), relative to this
// package's test working directory.
const bundledPacks = "../../../plugins/data"

// TestBundledLevelPacks: the level packs generated by
// scripts/prepare-level-packs.mjs load as valid levels packs with their
// scheme names, units and levels in easy-to-hard order, carry a licence
// and attribution, and import cleanly — into an empty lexicon every form
// is skipped and reported, none fails the import.
func TestBundledLevelPacks(t *testing.T) {
	jlpt := []string{"N5", "N4", "N3", "N2", "N1"}
	cases := []struct {
		id, name, language, unit string
		levels                   []string
		total                    int // forms over all levels; 0 = not pinned
	}{
		{"jlpt-kanji", "JLPT (kanji)", "ja", "character", jlpt, 0},
		{"jlpt-words", "JLPT (vocabulary)", "ja", "word", jlpt, 0},
	}
	for _, c := range cases {
		t.Run(c.id, func(t *testing.T) {
			dir := filepath.Join(bundledPacks, c.id)
			p, err := dict.LoadPack(dir)
			if err != nil {
				t.Fatalf("LoadPack: %v", err)
			}
			m := p.Manifest
			if m.ID != c.id || m.Name != c.name || m.Language != c.language || m.Type != dict.TypeLevels {
				t.Errorf("manifest = %+v, want id %s, name %q, language %s, type levels", m, c.id, c.name, c.language)
			}
			if m.License != "MIT" || m.Attribution == "" {
				t.Errorf("license %q, attribution %q; want MIT with an attribution", m.License, m.Attribution)
			}
			for _, f := range []string{"LICENSE", "ATTRIBUTION.md"} {
				if _, err := os.Stat(filepath.Join(dir, f)); err != nil {
					t.Errorf("%s: %v", f, err)
				}
			}

			raw, err := os.ReadFile(filepath.Join(dir, "levels.json"))
			if err != nil {
				t.Fatal(err)
			}
			var data struct {
				Unit   string `json:"unit"`
				Levels []struct {
					Name    string            `json:"name"`
					Entries []json.RawMessage `json:"entries"` // a form, or {"form", "reading"}
				} `json:"levels"`
			}
			if err := json.Unmarshal(raw, &data); err != nil {
				t.Fatal(err)
			}
			if data.Unit != c.unit {
				t.Errorf("unit = %q, want %q", data.Unit, c.unit)
			}
			var names []string
			total := 0
			for _, lv := range data.Levels {
				names = append(names, lv.Name)
				if len(lv.Entries) == 0 {
					t.Errorf("level %s is empty", lv.Name)
				}
				total += len(lv.Entries)
			}
			if !slices.Equal(names, c.levels) {
				t.Errorf("levels = %q, want %q", names, c.levels)
			}
			if c.total != 0 && total != c.total {
				t.Errorf("%d forms, want %d", total, c.total)
			}

			res, err := levels.Import(context.Background(), newDB(t), p)
			if err != nil {
				t.Fatalf("Import into an empty lexicon: %v", err)
			}
			if res.Levels != len(c.levels) || res.Members != 0 || len(res.Skipped) != total {
				t.Errorf("Import = %d levels, %d members, %d skipped; want %d, 0, %d",
					res.Levels, res.Members, len(res.Skipped), len(c.levels), total)
			}
		})
	}
}
